const root=document.querySelector('.security-architecture');
if(root){
 const nodes=[...root.querySelectorAll('.security-arch-lane article')];
 const key=text=>text.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/(^-|-$)/g,'');
 const metadata={
  'synthetic-data':{icon:'EVT',owner:'BTR EVENT FABRIC',control:'Revision + playhead contract',evidence:'Synthetic events and tracking only',risk:'Future or incompatible records are rejected.'},
  'viewer-intent':{icon:'ASK',owner:'AUDIENCE INPUT',control:'Question treated as untrusted text',evidence:'Language and audience preference',risk:'Viewer text never selects tools or expands evidence.'},
  'container-apps-ingress':{icon:'API',owner:'AZURE CONTAINER APPS',control:'HTTPS + origin + quota guard',evidence:'Verified proxy identity and bounded body',risk:'Spoofed forwarding values and excess streams are rejected.'},
  'entra-id-rbac':{icon:'ID',owner:'MICROSOFT ENTRA',control:'User-assigned managed identity',evidence:'Four least-privilege Azure roles',risk:'No application secret is required for Azure dependencies.'},
  'front-door-apim':{icon:'WAF',owner:'PRODUCTION OPTION',control:'WAF + API product policy',evidence:'Global edge telemetry',risk:'Proposed hardening; not connected to this prototype.'},
  'azure-openai':{icon:'AI',owner:'AZURE OPENAI',control:'Separate specialist handoffs',evidence:'Bounded public packets + prior accepted contribution',risk:'Drafts remain private until the claim gate accepts them.'},
  'deterministic-code':{icon:'ƒ',owner:'BTR POLICY ENGINE',control:'Calculation + citation gate',evidence:'Source IDs, units, cutoff and revision',risk:'Unsupported numbers, actors and causal claims fail closed.'},
  'microsoft-foundry':{icon:'F',owner:'MICROSOFT FOUNDRY',control:'Independent advisory referee',evidence:'Public trace and resolved citations',risk:'Foundry cannot override the deterministic release gate.'},
  'azure-blob-storage':{icon:'DB',owner:'AZURE STORAGE',control:'ETag checkpoint + retention',evidence:'Completed stages and recovery generation',risk:'Stale writers lose and expired agent records are deleted.'},
  'public-receipts':{icon:'LOG',owner:'BTR AUDIT LEDGER',control:'Immutable execution labels',evidence:'Execution ID, engine, latency and delivery state',risk:'Replay cannot masquerade as a fresh model request.'},
  'sentinel-purview':{icon:'SOC',owner:'PRODUCTION OPTION',control:'Detection + lineage governance',evidence:'Cloud and application telemetry',risk:'Proposed hardening; not connected to this prototype.'},
  'read-only-outputs':{icon:'TV',owner:'AUDIENCE DELIVERY',control:'Expiring read-only capability',evidence:'One verified revision',risk:'A viewer cannot mutate production state.'},
  'broadcast-contract':{icon:'GFX',owner:'BROADCAST OUTPUT',control:'Timed machine-readable cue',evidence:'Audience, sources, revision and expiry',risk:'A stale cue expires instead of lingering on screen.'}
 };
 for(const node of nodes){const label=node.querySelector('small')?.textContent||'',id=key(label);node.dataset.node=id;node.tabIndex=0;node.setAttribute('role','button');node.setAttribute('aria-label',`Inspect ${node.querySelector('strong')?.textContent||label}`);const badge=document.createElement('b');badge.className='security-node-icon';badge.textContent=metadata[id]?.icon||'•';node.prepend(badge);}
 const toolbar=document.createElement('div');toolbar.className='security-arch-toolbar';toolbar.innerHTML='<div><span>LIVE ARCHITECTURE TRACE</span><strong>Choose a path and watch the controls respond.</strong></div><div role="group" aria-label="Architecture trace"><button type="button" data-trace="live" class="is-active">Live moment</button><button type="button" data-trace="correction">Evidence correction</button><button type="button" data-trace="recovery">Failure recovery</button><button type="button" data-trace="blocked">Blocked request</button></div><button type="button" class="security-trace-play">▶ Trace this path</button>';
 root.querySelector('header').after(toolbar);
 const canvas=root.querySelector('.security-arch-canvas'),workspace=document.createElement('div');workspace.className='security-arch-workspace';canvas.before(workspace);workspace.append(canvas);
 const inspector=document.createElement('aside');inspector.className='security-arch-inspector';inspector.setAttribute('aria-live','polite');inspector.innerHTML='<header><span>SELECTED CONTROL</span><b data-inspector-state>RUNNING NOW</b></header><div class="security-inspector-icon" data-inspector-icon></div><small data-inspector-owner></small><h3 data-inspector-title></h3><p data-inspector-copy></p><dl><div><dt>CONTROL</dt><dd data-inspector-control></dd></div><div><dt>EVIDENCE</dt><dd data-inspector-evidence></dd></div><div><dt>FAILS SAFE</dt><dd data-inspector-risk></dd></div></dl><footer><i></i><span data-inspector-flow>Ready to trace a match moment.</span></footer>';
 workspace.append(inspector);
 const trace=document.createElement('ol');trace.className='security-trace-timeline';trace.setAttribute('aria-label','Current architecture trace');root.querySelector('footer').before(trace);
 const paths={
  live:['synthetic-data','container-apps-ingress','entra-id-rbac','azure-openai','deterministic-code','microsoft-foundry','azure-blob-storage','public-receipts','read-only-outputs','broadcast-contract'],
  correction:['viewer-intent','container-apps-ingress','entra-id-rbac','deterministic-code','microsoft-foundry','public-receipts','read-only-outputs','broadcast-contract'],
  recovery:['synthetic-data','container-apps-ingress','entra-id-rbac','azure-openai','azure-blob-storage','public-receipts','read-only-outputs'],
  blocked:['viewer-intent','container-apps-ingress']
 };
 const traceCopy={live:'A synthetic moment becomes a checked story on two audience surfaces.',correction:'A changed observation forces a recalculation, withdrawal and revised public line.',recovery:'Completed specialists restore from Blob checkpoints; only unfinished work runs again.',blocked:'The request guard refuses untrusted authority before any model request is reserved.'};
 let selected='live',timer=null;
 function inspect(node,flowText){
  if(!node)return;nodes.forEach(item=>item.classList.toggle('is-selected',item===node));const id=node.dataset.node,data=metadata[id]||{},future=node.dataset.kind==='future';
  inspector.querySelector('[data-inspector-state]').textContent=future?'PRODUCTION OPTION':'RUNNING NOW';inspector.querySelector('[data-inspector-state]').dataset.kind=future?'future':'live';inspector.querySelector('[data-inspector-icon]').textContent=data.icon||'•';inspector.querySelector('[data-inspector-owner]').textContent=data.owner||node.querySelector('small')?.textContent;inspector.querySelector('[data-inspector-title]').textContent=node.querySelector('strong')?.textContent||'';inspector.querySelector('[data-inspector-copy]').textContent=node.querySelector('p')?.textContent||'';inspector.querySelector('[data-inspector-control]').textContent=data.control||'Declared architecture control';inspector.querySelector('[data-inspector-evidence]').textContent=data.evidence||'Declared source record';inspector.querySelector('[data-inspector-risk]').textContent=data.risk||'The stage withholds output when its contract fails.';inspector.querySelector('[data-inspector-flow]').textContent=flowText||`Inspecting ${node.querySelector('strong')?.textContent}.`;
 }
 function reset(){if(timer)clearTimeout(timer);timer=null;nodes.forEach(node=>node.classList.remove('is-flowing','is-complete','is-path'));trace.replaceChildren();for(const id of paths[selected]){const node=nodes.find(item=>item.dataset.node===id);node?.classList.add('is-path');const item=document.createElement('li');item.dataset.node=id;item.innerHTML=`<i></i><span>${node?.querySelector('strong')?.textContent||id}</span><small>WAITING</small>`;item.onclick=()=>node&&inspect(node);trace.append(item);}inspector.querySelector('[data-inspector-flow]').textContent=traceCopy[selected];}
 function run(index=0){const path=paths[selected],items=[...trace.children];if(index===0){reset();toolbar.classList.add('is-running');toolbar.querySelector('.security-trace-play').textContent='Tracing…';}if(index>=path.length){toolbar.classList.remove('is-running');toolbar.querySelector('.security-trace-play').textContent='↺ Trace again';inspector.querySelector('[data-inspector-flow]').textContent=selected==='blocked'?'BLOCKED BEFORE MODEL EXECUTION · ZERO AI REQUESTS':'TRACE COMPLETE · AUDIENCE OUTPUT IS SOURCE-BOUND';return;}const node=nodes.find(item=>item.dataset.node===path[index]);if(index)nodes.find(item=>item.dataset.node===path[index-1])?.classList.replace('is-flowing','is-complete');node?.classList.add('is-flowing');items[index]?.classList.add('is-current');items[index]?.querySelector('small')&&(items[index].querySelector('small').textContent=index===path.length-1&&selected==='blocked'?'BLOCKED':'ACTIVE');if(index)items[index-1]?.classList.replace('is-current','is-complete');inspect(node,`${String(index+1).padStart(2,'0')} / ${String(path.length).padStart(2,'0')} · ${traceCopy[selected]}`);timer=setTimeout(()=>run(index+1),520);}
 for(const node of nodes){node.onclick=()=>inspect(node);node.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();inspect(node);}};}
 toolbar.querySelectorAll('[data-trace]').forEach(button=>button.onclick=()=>{selected=button.dataset.trace;toolbar.querySelectorAll('[data-trace]').forEach(item=>item.classList.toggle('is-active',item===button));reset();inspect(nodes.find(item=>item.dataset.node===paths[selected][0]),traceCopy[selected]);});
 toolbar.querySelector('.security-trace-play').onclick=()=>run();
 reset();inspect(nodes.find(item=>item.dataset.node===paths.live[0]),traceCopy.live);
}
